eExceptionHandler();  if (app.Environment.IsDevelopment()) {     app.MapOpenApi(); }  app.MapGet("/", () => Results.Ok(CoreIdentity.Current))     .WithName("GetCoreIdentity"); app.MapHealthChecks("/health"); app.MapHealthChecks("/health/live", new HealthCheckOptions {     Predicate = static registration => registration.Tags.Contains("live") }); app.MapHealthChecks("/health/ready", new HealthCheckOptions {     Predicate = static registration => registration.Tags.Contains("ready") }); app.MapOrganizationEndpoints(); app.MapSecurityEndpoints(); app.MapAuditEndpoints(); app.MapLookupEndpoints(); app.MapCustomerEndpoints(); app.MapCatalogEndpoints(); app.MapArtworkFileEndpoints(); app.MapOrderEndpoints(); app.MapOrder360Endpoints(); app.MapBusinessProfileEndpoints(); app.MapPricingEndpoints(); app.MapFinanceEndpoints(); app.MapInventoryEndpoints(); app.MapProductionEndpoints(); app.MapQualityEndpoints(); app.MapLogisticsEndpoints(); app.MapWorkflowEndpoints(); app.MapBackgroundEndpoints(); app.MapClientApiEndpoints();  app.Run();  public partial class Program;